-- Modify "user_stats" table
ALTER TABLE "public"."user_stats" ADD COLUMN "total_submissions" bigint NOT NULL DEFAULT 0, ADD COLUMN "accepted_count" bigint NOT NULL DEFAULT 0;
-- Create "user_difficulty_stats" table
CREATE TABLE "public"."user_difficulty_stats" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "solved_count" bigint NOT NULL DEFAULT 0,
  "difficulty_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_difficulty_stats_difficulties_user_difficulty_stats" FOREIGN KEY ("difficulty_id") REFERENCES "public"."difficulties" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "user_difficulty_stats_users_difficulty_stats" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "userdifficultystats_user_id" to table: "user_difficulty_stats"
CREATE INDEX "userdifficultystats_user_id" ON "public"."user_difficulty_stats" ("user_id");
-- Create index "userdifficultystats_user_id_difficulty_id" to table: "user_difficulty_stats"
CREATE UNIQUE INDEX "userdifficultystats_user_id_difficulty_id" ON "public"."user_difficulty_stats" ("user_id", "difficulty_id");
-- Create "user_tag_stats" table
CREATE TABLE "public"."user_tag_stats" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "solved_count" bigint NOT NULL DEFAULT 0,
  "tag_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_tag_stats_tags_user_tag_stats" FOREIGN KEY ("tag_id") REFERENCES "public"."tags" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "user_tag_stats_users_tag_stats" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "usertagstats_user_id" to table: "user_tag_stats"
CREATE INDEX "usertagstats_user_id" ON "public"."user_tag_stats" ("user_id");
-- Create index "usertagstats_user_id_tag_id" to table: "user_tag_stats"
CREATE UNIQUE INDEX "usertagstats_user_id_tag_id" ON "public"."user_tag_stats" ("user_id", "tag_id");
